gcode_macro save_last_file.gcode:
{% set svv = printer.save_variables.variables %}

{% set filepath=printer.virtual_sdcard.file_path %}

{% set filename=filepath.split('/')%}

SAVE_VARIABLE VARIABLE=last_file VALUE='"{ filename[-1] }"'
SAVE_VARIABLE VARIABLE=filepath VALUE='"{ printer.virtual_sdcard.file_path }"'


M118 Last File: { filename[-1] }

gcode_macro clear_last_file.gcode:
{% set filename='' %}
{% set filepath='' %}
SAVE_VARIABLE VARIABLE=last_file VALUE='"{ filename }"'
SAVE_VARIABLE VARIABLE=filepath VALUE='"{ filepath }"'

gcode_macro RESUME_INTERRUPTED.gcode:
SET_GCODE_OFFSET Z=0 MOVE=0
{% set z_height = params.Z_HEIGHT|default(printer.save_variables.variables.power_resume_z)|float %}
{% set last_file = params.GCODE_FILE|default(printer.save_variables.variables.last_file)|string %}
m118 {last_file}

RUN_SHELL_COMMAND CMD=POWER_LOSS_RESUME PARAMS="{z_height} \"{last_file}\""
SDCARD_PRINT_FILE FILENAME=plr/"{last_file}"

gcode_macro LOG_Z.gcode:
{% set z_pos = printer.gcode_move.gcode_position.z %}
RESPOND MSG="Current Z is {z_pos}"
SAVE_VARIABLE VARIABLE=power_resume_z VALUE={z_pos}

gcode_macro FLASH_MCU.gcode:
{% set _mcu = params.MCU|string %}
{% if printer.idle_timeout.state != "Printing" %}
{action_call_remote_method("flash_mcu", mcu=_mcu)}
{% else %}
{action_respond_info("MCU flashing disabled during printing")}
{% endif %}

gcode_macro CANCEL_PRINT.gcode:
{% set client = printer['gcode_macro _CLIENT_VARIABLE']|default({}) %}
{% set allow_park = client.park_at_cancel|default(false)|lower == 'true' %}
{% set retract = client.cancel_retract|default(5.0)|abs %}

{% set park_x = "" if (client.park_at_cancel_x|default(none) is none)
else "X=" ~ client.park_at_cancel_x %}
{% set park_y = "" if (client.park_at_cancel_y|default(none) is none)
else "Y=" ~ client.park_at_cancel_y %}
{% set custom_park = park_x|length > 0 or park_y|length > 0 %}


{% if printer['gcode_macro RESUME'].restore_idle_timeout > 0 %}
SET_IDLE_TIMEOUT TIMEOUT={printer['gcode_macro RESUME'].restore_idle_timeout}
{% endif %}
{% if (custom_park or not printer.pause_resume.is_paused) and allow_park %} _TOOLHEAD_PARK_PAUSE_CANCEL {park_x} {park_y} {% endif %}
_CLIENT_RETRACT LENGTH={retract}
TURN_OFF_HEATERS
M106 S0
{client.user_cancel_macro|default("")}
SET_GCODE_VARIABLE MACRO=RESUME VARIABLE=idle_state VALUE=False

SET_PAUSE_NEXT_LAYER ENABLE=0
SET_PAUSE_AT_LAYER ENABLE=0 LAYER=0
CANCEL_PRINT_BASE

gcode_macro PAUSE.gcode:
{% set client = printer['gcode_macro _CLIENT_VARIABLE']|default({}) %}
{% set idle_timeout = client.idle_timeout|default(0) %}
{% set temp = printer[printer.toolhead.extruder].target if printer.toolhead.extruder != '' else 0 %}
{% set restore = False if printer.toolhead.extruder == ''
else True  if params.RESTORE|default(1)|int == 1 else False %}

SET_GCODE_VARIABLE MACRO=RESUME VARIABLE=last_extruder_temp VALUE="{{'restore': restore, 'temp': temp}}"

{% if idle_timeout > 0 %}
SET_GCODE_VARIABLE MACRO=RESUME VARIABLE=restore_idle_timeout VALUE={printer.configfile.settings.idle_timeout.timeout}
SET_IDLE_TIMEOUT TIMEOUT={idle_timeout}
{% endif %}
PAUSE_BASE
{client.user_pause_macro|default("")}
_TOOLHEAD_PARK_PAUSE_CANCEL {rawparams}

gcode_macro RESUME.gcode:
{% set client = printer['gcode_macro _CLIENT_VARIABLE']|default({}) %}
{% set velocity = printer.configfile.settings.pause_resume.recover_velocity %}
{% set sp_move = client.speed_move|default(velocity) %}
{% set runout_resume = True if client.runout_sensor|default("") == ""
else True if not printer[client.runout_sensor].enabled
else printer[client.runout_sensor].filament_detected %}
{% set can_extrude = True if printer.toolhead.extruder == ''
else printer[printer.toolhead.extruder].can_extrude %}
{% set do_resume = False %}
{% set prompt_txt = [] %}


{% if printer.idle_timeout.state|upper == "IDLE" or idle_state %}
SET_GCODE_VARIABLE MACRO=RESUME VARIABLE=idle_state VALUE=False
{% if last_extruder_temp.restore %}

RESPOND TYPE=echo MSG='{"Restoring \"%s\" temperature to %3.1f\u00B0C, this may take some time" % (printer.toolhead.extruder, last_extruder_temp.temp) }'
M109 S{last_extruder_temp.temp}
{% set do_resume = True %}
{% elif can_extrude %}
{% set do_resume = True %}
{% else %}
RESPOND TYPE=error MSG='{"Resume aborted !!! \"%s\" not hot enough, please heat up again and press RESUME" % printer.toolhead.extruder}'
{% set _d = prompt_txt.append("\"%s\" not hot enough, please heat up again and press RESUME" % printer.toolhead.extruder) %}
{% endif %}

{% elif can_extrude %}
{% set do_resume = True %}
{% else %}
RESPOND TYPE=error MSG='{"Resume aborted !!! \"%s\" not hot enough, please heat up again and press RESUME" % printer.toolhead.extruder}'
{% set _d = prompt_txt.append("\"%s\" not hot enough, please heat up again and press RESUME" % printer.toolhead.extruder) %}
{% endif %}
{% if runout_resume %}
{% if do_resume %}
{% if restore_idle_timeout > 0 %} SET_IDLE_TIMEOUT TIMEOUT={restore_idle_timeout} {% endif %}
{client.user_resume_macro|default("")}
_CLIENT_EXTRUDE
RESUME_BASE VELOCITY={params.VELOCITY|default(sp_move)}
{% endif %}
{% else %}
RESPOND TYPE=error MSG='{"Resume aborted !!! \"%s\" detects no filament, please load filament and press RESUME" % (client.runout_sensor.split(" "))[1]}'
{% set _d = prompt_txt.append("\"%s\" detects no filament, please load filament and press RESUME" % (client.runout_sensor.split(" "))[1]) %}
{% endif %}

{% if not (runout_resume and do_resume) %}
RESPOND TYPE=command MSG="action:prompt_begin RESUME aborted !!!"
{% for element in prompt_txt %}
RESPOND TYPE=command MSG='{"action:prompt_text %s" % element}'
{% endfor %}
RESPOND TYPE=command MSG="action:prompt_footer_button Ok|RESPOND TYPE=command MSG=action:prompt_end|info"
RESPOND TYPE=command MSG="action:prompt_show"
{% endif %}

gcode_macro SET_PAUSE_NEXT_LAYER.gcode:
{% set pause_next_layer = printer['gcode_macro SET_PRINT_STATS_INFO'].pause_next_layer %}
{% set ENABLE = params.ENABLE|default(1)|int != 0 %}
{% set MACRO = params.MACRO|default(pause_next_layer.call, True) %}
SET_GCODE_VARIABLE MACRO=SET_PRINT_STATS_INFO VARIABLE=pause_next_layer VALUE="{{ 'enable': ENABLE, 'call': MACRO }}"

gcode_macro SET_PAUSE_AT_LAYER.gcode:
{% set pause_at_layer = printer['gcode_macro SET_PRINT_STATS_INFO'].pause_at_layer %}
{% set ENABLE = params.ENABLE|int != 0 if params.ENABLE is defined
else params.LAYER is defined %}
{% set LAYER = params.LAYER|default(pause_at_layer.layer)|int %}
{% set MACRO = params.MACRO|default(pause_at_layer.call, True) %}
SET_GCODE_VARIABLE MACRO=SET_PRINT_STATS_INFO VARIABLE=pause_at_layer VALUE="{{ 'enable': ENABLE, 'layer': LAYER, 'call': MACRO }}"

gcode_macro SET_PRINT_STATS_INFO.gcode:
{% if pause_next_layer.enable %}
RESPOND TYPE=echo MSG='{"%s, forced by pause_next_layer" % pause_next_layer.call}'
{pause_next_layer.call}
SET_PAUSE_NEXT_LAYER ENABLE=0
{% elif pause_at_layer.enable and params.CURRENT_LAYER is defined and params.CURRENT_LAYER|int == pause_at_layer.layer %}
RESPOND TYPE=echo MSG='{"%s, forced by pause_at_layer [%d]" % (pause_at_layer.call, pause_at_layer.layer)}'
{pause_at_layer.call}
SET_PAUSE_AT_LAYER ENABLE=0
{% endif %}
SET_PRINT_STATS_INFO_BASE {rawparams}

gcode_macro _TOOLHEAD_PARK_PAUSE_CANCEL.gcode:
{% set client = printer['gcode_macro _CLIENT_VARIABLE']|default({}) %}
{% set velocity = printer.configfile.settings.pause_resume.recover_velocity %}
{% set use_custom     = client.use_custom_pos|default(false)|lower == 'true' %}
{% set custom_park_x  = client.custom_park_x|default(0.0) %}
{% set custom_park_y  = client.custom_park_y|default(0.0) %}
{% set park_dz        = client.custom_park_dz|default(2.0)|abs %}
{% set sp_hop         = client.speed_hop|default(15) * 60 %}
{% set sp_move        = client.speed_move|default(velocity) * 60 %}

{% set origin    = printer.gcode_move.homing_origin %}
{% set act       = printer.gcode_move.gcode_position %}
{% set max       = printer.toolhead.axis_maximum %}
{% set cone      = printer.toolhead.cone_start_z|default(max.z) %}
{% set round_bed = True if printer.configfile.settings.printer.kinematics is in ['delta','polar','rotary_delta','winch']
else False %}

{% set z_min = params.Z_MIN|default(0)|float %}
{% set z_park = [[(act.z + park_dz), z_min]|max, (max.z - origin.z)]|min %}
{% set x_park = params.X       if params.X is defined
else custom_park_x  if use_custom
else 0.0            if round_bed
else (max.x - 5.0) %}
{% set y_park = params.Y       if params.Y is defined
else custom_park_y  if use_custom
else (max.y - 5.0)  if round_bed and z_park < cone
else 0.0            if round_bed
else (max.y - 5.0) %}

_CLIENT_RETRACT
{% if "xyz" in printer.toolhead.homed_axes %}
G90
G1 Z{z_park} F{sp_hop}
G1 X{x_park} Y{y_park} F{sp_move}
{% if not printer.gcode_move.absolute_coordinates %} G91 {% endif %}
{% else %}
RESPOND TYPE=echo MSG='Printer not homed'
{% endif %}

gcode_macro _CLIENT_EXTRUDE.gcode:
{% set client = printer['gcode_macro _CLIENT_VARIABLE']|default({}) %}
{% set use_fw_retract = (client.use_fw_retract|default(false)|lower == 'true') and (printer.firmware_retraction is defined) %}
{% set length = params.LENGTH|default(client.unretract)|default(1.0)|float %}
{% set speed = params.SPEED|default(client.speed_unretract)|default(35) %}
{% set absolute_extrude = printer.gcode_move.absolute_extrude %}

{% if printer.toolhead.extruder != '' %}
{% if printer[printer.toolhead.extruder].can_extrude %}
{% if use_fw_retract %}
{% if length < 0 %}
G10
{% else %}
G11
{% endif %}
{% else %}
M83
G1 E{length} F{(speed|float|abs) * 60}
{% if absolute_extrude %}
M82
{% endif %}
{% endif %}
{% else %}
RESPOND TYPE=echo MSG='{"\"%s\" not hot enough" % printer.toolhead.extruder}'
{% endif %}
{% endif %}

gcode_macro _CLIENT_RETRACT.gcode:
{% set client = printer['gcode_macro _CLIENT_VARIABLE']|default({}) %}
{% set length = params.LENGTH|default(client.retract)|default(1.0)|float %}
{% set speed = params.SPEED|default(client.speed_retract)|default(35) %}

_CLIENT_EXTRUDE LENGTH=-{length|float|abs} SPEED={speed|float|abs}

gcode_macro _CLIENT_LINEAR_MOVE.gcode:
{% set x_move = "X" ~ params.X if params.X is defined else "" %}
{% set y_move = "Y" ~ params.Y if params.Y is defined else "" %}
{% set z_move = "Z" ~ params.Z if params.Z is defined else "" %}
{% set e_move = "E" ~ params.E if params.E is defined else "" %}
{% set rate = "F" ~ params.F if params.F is defined else "" %}
{% set ABSOLUTE = params.ABSOLUTE | default(0) | int != 0 %}
{% set ABSOLUTE_E = params.ABSOLUTE_E | default(0) | int != 0 %}
SAVE_GCODE_STATE NAME=_client_movement
{% if x_move or y_move or z_move %}
G9{ 0 if ABSOLUTE else 1 }
{% endif %}
{% if e_move %}
M8{ 2 if ABSOLUTE_E else 3 }
{% endif %}
G1 { x_move } { y_move } { z_move } { e_move } { rate }
RESTORE_GCODE_STATE NAME=_client_movement

gcode_macro SETTLE_BELTS.gcode:
{% set speed = params.SPEED|default(15000)|int %}
{% set iterations = params.ITER|default(5)|int %}


{% set center_x = printer.toolhead.axis_maximum.x / 2.0 %}
{% set center_y = printer.toolhead.axis_maximum.y / 2.0 %}
{% set radius = 50 %}
{% set start_y = center_y - radius %}

SAVE_GCODE_STATE NAME=settle_belts_state
G28
G90
G1 Z20 F3000


{% for i in range(iterations) %}
G1 X{center_x} Y{start_y} F{speed}
G2 X{center_x} Y{start_y} I0 J{radius} F{speed}
G3 X{center_x} Y{start_y} I0 J{radius} F{speed}
{% endfor %}

G1 X{center_x} Y{center_y} F{speed}
RESTORE_GCODE_STATE NAME=settle_belts_state
M117 Belts Settled

gcode_macro CLEAN_NOZZLE.gcode:
{% set cfg = printer["gcode_macro CLEAN_NOZZLE"] %}
{% set x_min = params.X_MIN|default(cfg.brush_x_min)|float %}
{% set x_max = params.X_MAX|default(cfg.brush_x_max)|float %}
{% set y = params.Y|default(cfg.brush_y)|float %}
{% set z = params.Z|default(cfg.brush_z)|float %}
{% set travel_z = params.TRAVEL_Z|default(cfg.travel_z)|float %}
{% set wipes = params.WIPES|default(cfg.wipe_count)|int %}
{% set speed = params.SPEED|default(cfg.wipe_speed)|int %}

{% if z < 4.5 %}
{ action_raise_error("CLEAN_NOZZLE: brush_z too low. Refusing to move below Z=4.5") }
{% endif %}

{% if travel_z <= z + 3 %}
{ action_raise_error("CLEAN_NOZZLE: travel_z must be at least brush_z + 3mm") }
{% endif %}

SAVE_GCODE_STATE NAME=clean_nozzle_state
G90

{% if "xyz" not in printer.toolhead.homed_axes %}
G28
{% endif %}

G0 Z{travel_z} F3000
G0 X{x_min} Y{y} F6000
G0 Z{z} F1200

{% for i in range(wipes) %}
G0 X{x_max} Y{y} F{speed}
G0 X{x_min} Y{y} F{speed}
{% endfor %}

G0 Z{travel_z} F3000
RESTORE_GCODE_STATE NAME=clean_nozzle_state

gcode_macro CQGL.gcode:
{% if printer.quad_gantry_level.applied == False %}
M117 Conditional QGL...
G90

CG28

QUAD_GANTRY_LEVEL
G28 Z
{% endif %}


{% set center_x = printer.toolhead.axis_maximum.x / 2.0 %}
{% set center_y = printer.toolhead.axis_maximum.y / 2.0 %}


G0 X{center_x} Y{center_y} Z30 F3600

gcode_macro M109.gcode:
{% set s = params.S|float %}


M104 {% for p in params %}{'%s%s' % (p, params[p])}{% endfor %}



{% if s != 0 %}
TEMPERATURE_WAIT SENSOR=extruder MINIMUM={s} MAXIMUM={s+2}
{% endif %}

gcode_macro M190.gcode:
{% set s = params.S|float %}


M140 {% for p in params %}{'%s%s' % (p, params[p])}{% endfor %}



{% if s != 0 %}
TEMPERATURE_WAIT SENSOR=heater_bed MINIMUM={s} MAXIMUM={s+3}
{% endif %}

gcode_macro SETTLE_Z_BELTS.gcode:
{% set speed = 12000 %}
{% set iterations = 10 %}
{% set z_max = 150 %}
{% set z_min = 30 %}



{% if "xyz" not in printer.toolhead.homed_axes %}
M117 Homing...
G28
{% endif %}


G90
M117 Centering Toolhead...


{% set center_x = printer.toolhead.axis_maximum.x / 2 %}
{% set center_y = printer.toolhead.axis_maximum.y / 2 %}
G0 X{center_x} Y{center_y} Z{z_min} F{speed}


M117 Settling Z Belts...
{% for i in range(iterations) %}
M118 Cycle {i + 1} / {iterations} : Moving Up...
G0 Z{z_max} F{speed}
M118 Cycle {i + 1} / {iterations} : Moving Down...
G0 Z{z_min} F{speed}
{% endfor %}


M117 Z Belts Settled.
M118 Z Belts Settling Complete. Please run QUAD_GANTRY_LEVEL now.

gcode_macro TEST_SPEED.gcode:
{% set speed  = params.SPEED|default(printer.configfile.settings.printer.max_velocity)|int %}

{% set iterations = params.ITERATIONS|default(5)|int %}

{% set accel  = params.ACCEL|default(printer.configfile.settings.printer.max_accel)|int %}

{% set min_cruise_ratio = params.MIN_CRUISE_RATIO|default(0.5)|float %}

{% set bound = params.BOUND|default(20)|int %}

{% set smallpatternsize = SMALLPATTERNSIZE|default(20)|int %}



{% set x_min = printer.toolhead.axis_minimum.x %}
{% if x_min < 0 %}
{% set x_min = 0 %}
{% endif %}

{% set y_min = printer.toolhead.axis_minimum.y %}
{% if y_min < 0 %}
{% set y_min = 0 %}
{% endif %}

{% set x_min = x_min + bound %}
{% set x_max = printer.toolhead.axis_maximum.x - bound %}
{% set y_min = y_min + bound %}
{% set y_max = printer.toolhead.axis_maximum.y - bound %}



{% set x_center = (printer.toolhead.axis_minimum.x|float + printer.toolhead.axis_maximum.x|float ) / 2 %}
{% set y_center = (printer.toolhead.axis_minimum.y|float + printer.toolhead.axis_maximum.y|float ) / 2 %}


{% set x_center_min = x_center - (smallpatternsize/2) %}
{% set x_center_max = x_center + (smallpatternsize/2) %}
{% set y_center_min = y_center - (smallpatternsize/2) %}
{% set y_center_max = y_center + (smallpatternsize/2) %}


SAVE_GCODE_STATE NAME=TEST_SPEED


{ action_respond_info("TEST_SPEED: starting %d iterations at speed %d, accel %d" % (iterations, speed, accel)) }


M400
G28

{% if printer.configfile.settings.quad_gantry_level %}
{% if printer.quad_gantry_level.applied == False %}
QUAD_GANTRY_LEVEL
G28 Z
{% endif %}
{% endif %}

G90
G1 X{printer.toolhead.axis_maximum.x-50} Y{printer.toolhead.axis_maximum.y-50} F{30*60}
M400
G28 X Y
G0 X{printer.toolhead.axis_maximum.x-1} Y{printer.toolhead.axis_maximum.y-1} F{30*60}
G4 P1000
GET_POSITION


G0 X{x_min} Y{y_min} Z{bound + 10} F{speed*60}


{% if printer.configfile.settings.printer.minimum_cruise_ratio is defined %}
SET_VELOCITY_LIMIT VELOCITY={speed} ACCEL={accel} MINIMUM_CRUISE_RATIO={min_cruise_ratio}
{% else %}
SET_VELOCITY_LIMIT VELOCITY={speed} ACCEL={accel} ACCEL_TO_DECEL={accel / 2}
{% endif %}

{% for i in range(iterations) %}

G0 X{x_min} Y{y_min} F{speed*60}
G0 X{x_max} Y{y_max} F{speed*60}
G0 X{x_min} Y{y_min} F{speed*60}
G0 X{x_max} Y{y_min} F{speed*60}
G0 X{x_min} Y{y_max} F{speed*60}
G0 X{x_max} Y{y_min} F{speed*60}


G0 X{x_min} Y{y_min} F{speed*60}
G0 X{x_min} Y{y_max} F{speed*60}
G0 X{x_max} Y{y_max} F{speed*60}
G0 X{x_max} Y{y_min} F{speed*60}


G0 X{x_center_min} Y{y_center_min} F{speed*60}
G0 X{x_center_max} Y{y_center_max} F{speed*60}
G0 X{x_center_min} Y{y_center_min} F{speed*60}
G0 X{x_center_max} Y{y_center_min} F{speed*60}
G0 X{x_center_min} Y{y_center_max} F{speed*60}
G0 X{x_center_max} Y{y_center_min} F{speed*60}


G0 X{x_center_min} Y{y_center_min} F{speed*60}
G0 X{x_center_min} Y{y_center_max} F{speed*60}
G0 X{x_center_max} Y{y_center_max} F{speed*60}
G0 X{x_center_max} Y{y_center_min} F{speed*60}
{% endfor %}


{% if printer.configfile.settings.printer.minimum_cruise_ratio is defined %}
SET_VELOCITY_LIMIT VELOCITY={printer.configfile.settings.printer.max_velocity} ACCEL={printer.configfile.settings.printer.max_accel} MINIMUM_CRUISE_RATIO={printer.configfile.settings.printer.minimum_cruise_ratio}
{% else %}
SET_VELOCITY_LIMIT VELOCITY={printer.configfile.settings.printer.max_velocity} ACCEL={printer.configfile.settings.printer.max_accel} ACCEL_TO_DECEL={printer.configfile.settings.printer.max_accel_to_decel}
{% endif %}


M400
G28

G90
G0 X{printer.toolhead.axis_maximum.x-1} Y{printer.toolhead.axis_maximum.y-1} F{30*60}
G4 P1000
GET_POSITION


RESTORE_GCODE_STATE NAME=TEST_SPEED

